import {FARMS} from './regional-farms.js?v=neighbours16';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function installNeighbours({world,state,player,modal,walk,toast}){
 function find(id,name){const v=world.farms.get(id);return v?.people?.residents.find(r=>r.name===name)||v?.people?.pets.find(r=>(r.type==='dog'?'Buddy':'Miso')===name);}
 window.openNeighbour=(id,name,topic='hello')=>{const p=FARMS.find(p=>p.id===id),r=find(id,name);if(!p||!r)return toast('This resident is still arriving.');const near=Math.hypot(player.position.x-r.agent.x,player.position.z-r.agent.z)<4,child=r.role==='child',pet=!!r.type,own=!!state.regionalFarms?.owned[id],lines=pet?(r.type==='dog'?['Woof! Buddy wags his tail.','Buddy sniffs the path, then watches you.']:['Miso gives a slow blink.','Miso stretches and flicks her tail.']):topic==='farm'?[p.ability,own?'We help look after your farm. Start and collect production at the farm entrance.':'This farm already has its own house, working buildings and fields. You can inspect it before buying.']:child?['I like watching the animals from the garden!','Have you met our dog and cat?']:['Hello! Welcome to '+p.name+'.','The animals keep their own pace here. Some graze while others wander or rest.'];const reply=lines[r.chatIndex=(r.chatIndex??-1)+1>=lines.length?0:(r.chatIndex??-1)+1];modal('<span class="service-tag">'+esc(p.name)+'</span><h2>'+esc(name)+(child?' · family member':pet?' · farm '+r.type:' · '+esc(r.role))+'</h2><p>'+esc(near?reply:'You can see '+name+' around the farm. Walk closer to say hello.')+'</p>'+(near?'<div class="choice"><button onclick="openNeighbour(\''+id+'\',\''+esc(name)+'\')">'+(pet?'Interact again':'Say hello')+'</button>'+(!pet&&!child?'<button onclick="openNeighbour(\''+id+'\',\''+esc(name)+'\',\'farm\')">Ask about the farm</button>':'')+'</div>':'<button onclick="visitNeighbour(\''+id+'\',\''+esc(name)+'\')">Walk over</button>')+'<button onclick="openRegionalFarm(\''+id+'\')">Inspect farm</button><p class="asset-note">Residents follow local behaviour routines and contextual dialogue.</p>');if(near)r.agent.pausedUntil=Date.now()+45000;};
 window.visitNeighbour=(id,name)=>{window.home?.();const r=find(id,name);if(!r)return;document.querySelector('dialog').close();walk(r.agent.x,r.agent.z+1.1,'Meet '+name,()=>window.openNeighbour(id,name));r.agent.pausedUntil=Date.now()+120000;};
 document.querySelector('dialog').addEventListener('close',()=>{for(const v of world.farms.values())for(const r of [...(v.people?.residents||[]),...(v.people?.pets||[])])r.agent.pausedUntil=0;});
}
